\documentclass[11pt]{article}
\usepackage{amsmath}

\title{Uncertainty in Runoff Simulation for a Mountainous Catchment under the Xinanjiang Model}
\author{L.~Wang and M.~Chen}
\date{May 2026}

\begin{document}
\maketitle

\begin{abstract}
Rainfall-runoff models of mountainous catchments are sensitive to
parameter estimates derived from short records. We quantify the
uncertainty of Xinanjiang model simulations for the upper Jinhua basin
using a generalised likelihood framework, and we identify which
parameters dominate the predictive variance during flood events.
\end{abstract}

